import { useEffect, useState } from "react"
import { io } from "socket.io-client"

const socket = io("http://localhost:5001")

function App() {
  const [email, setEmail] = useState("")
  const [name, setName] = useState("")
  const [user, setUser] = useState(null)
  const [other, setOther] = useState("Ravi")
  const [msg, setMsg] = useState("")
  const [list, setList] = useState([])
  const [typing, setTyping] = useState("")

  const login = () => {
    if (!email || !name) return alert("Enter name and email")
    socket.emit("join", { email, name })
  }

  const send = () => {
    if (!msg.trim()) return
    socket.emit("send_message", {
      sender: user.name,
      receiver: other,
      text: msg
    })
    setMsg("")
  }

  const handleTyping = () => {
    socket.emit("typing", { from: user.name, to: other })
  }

  useEffect(() => {
    socket.on("login_success", (u) => setUser(u))
    socket.on("receive_message", (data) => setList(prev => [...prev, data]))
    socket.on("typing", (u) => {
      setTyping(u + " typing...")
      setTimeout(() => setTyping(""), 1000)
    })
    return () => {
      socket.off("login_success")
      socket.off("receive_message")
      socket.off("typing")
    }
  }, [])

  if (!user) {
    return (
      <div style={{ padding: "50px" }}>
        <h2>Login / Signup</h2>
        <input placeholder="Name" value={name} onChange={e => setName(e.target.value)} />
        <input placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} />
        <button onClick={login}>Enter Chat</button>
      </div>
    )
  }

  return (
    <div style={{ padding: "50px" }}>
      <h2>{user.name} chatting with {other}</h2>
      <input value={msg} onChange={e => setMsg(e.target.value)} onKeyUp={handleTyping} />
      <button onClick={send}>Send</button>
      <p>{typing}</p>
      <div>
        {list.map((m, i) => (
          <p key={i}><b>{m.sender}:</b> {m.text}</p>
        ))}
      </div>
    </div>
  )
}

export default App
